insert into project_control.decisions(id,title,decision,reason,affected_tasks,owner,status,decided_at) values ('DEC-001','مصدر حقيقة واحد','اعتماد نظام project_control والوثيقة التطبيقية V2 كمصدر رسمي، مع إبقاء جميع المصادر القديمة للرجوع.','منع تضارب الوثائق وفقد المتطلبات','{G00-01,G01-01}'::text[],'Owner','approved','2026-07-20'::timestamptz) on conflict(id) do update set title=excluded.title,decision=excluded.decision,reason=excluded.reason,affected_tasks=excluded.affected_tasks,owner=excluded.owner,status=excluded.status,decided_at=excluded.decided_at;
insert into project_control.decisions(id,title,decision,reason,affected_tasks,owner,status,decided_at) values ('DEC-002','منع التعديل المباشر على main','كل تغيير عبر فرع وPull Request واختبارات وRollback.','تقليل الأعطال والتعارض','{G01-01,G01-02}'::text[],'Technical Lead','approved','2026-07-20'::timestamptz) on conflict(id) do update set title=excluded.title,decision=excluded.decision,reason=excluded.reason,affected_tasks=excluded.affected_tasks,owner=excluded.owner,status=excluded.status,decided_at=excluded.decided_at;
